import { useEffect, type RefObject } from 'react'
import { paintDemoFrame } from '../lib/demo'

/**
 * Paints the synthetic demo camera frame into a canvas on an animation loop.
 *
 * Used only while Demo Mode is on: the painter lives in `lib/demo.ts`, so even
 * the picture the "camera" shows is generated by the one module allowed to
 * produce synthetic content — and it stamps itself `DEMO CAMERA FEED`.
 */
export function useDemoFeedPainter(
  canvasRef: RefObject<HTMLCanvasElement | null>,
  enabled: boolean,
  board: { widthMm: number; heightMm: number },
): void {
  useEffect(() => {
    const canvas = canvasRef.current
    if (!enabled || !canvas) return
    const ctx = canvas.getContext('2d')
    if (!ctx) return
    let raf = 0
    const started = performance.now()
    const paint = () => {
      const t = (performance.now() - started) / 1000
      ctx.clearRect(0, 0, canvas.width, canvas.height)
      try {
        paintDemoFrame(ctx, canvas.width, canvas.height, {
          widthMm: board.widthMm,
          heightMm: board.heightMm,
          t,
        })
      } catch {
        /* a partially constructed context must never break the page */
      }
      raf = requestAnimationFrame(paint)
    }
    raf = requestAnimationFrame(paint)
    return () => cancelAnimationFrame(raf)
  }, [canvasRef, enabled, board.widthMm, board.heightMm])
}
